    44  void bn_init(bn_t a, int digits) {
    45  #if ALLOC == DYNAMIC
    46          if (digits % RLC_BN_SIZE != 0) {
    47                  /* Pad the number of digits to a multiple of the block. */
    48                  digits += (RLC_BN_SIZE - digits % RLC_BN_SIZE);
    49          }
    50
    51          if (a != NULL) {
    52                  a->dp = NULL;
    53  #if ALIGN == 1
    54                  a->dp = (dig_t *)malloc(digits * sizeof(dig_t));
    55  #elif OPSYS == WINDOWS
    56                  a->dp = _aligned_malloc(digits * sizeof(dig_t), ALIGN);
    57  #else
    58                  int r = posix_memalign((void **)&a->dp, ALIGN, digits * sizeof(dig_t));
    59                  if (r == ENOMEM) {
    60                          RLC_THROW(ERR_NO_MEMORY);
    61                  }
    62                  if (r == EINVAL) {
    63                          RLC_THROW(ERR_NO_VALID);
    64                  }
    65  #endif
    66          }
    67
    68          if (a->dp == NULL) {
    69                  free(a);
    70                  RLC_THROW(ERR_NO_MEMORY);
    71          }
    72  #else
    73          /* Verify if the number of digits is sane. */
    74          if (digits > RLC_BN_SIZE) {
    75                  RLC_THROW(ERR_NO_PRECI);
    76                  return;
    77          } else {
    78                  digits = RLC_BN_SIZE;
    79          }
    80  #endif
    81          if (a != NULL) {
    82                  a->used = 0;
    83                  a->alloc = digits;
    84                  a->sign = RLC_POS;
    85          }
    86  }
    87
    88  void bn_clean(bn_t a) {
    89  #if ALLOC == DYNAMIC
    90          if (a != NULL) {
    91                  if (a->dp != NULL) {
    92  #if OPSYS == WINDOWS && ALIGN > 1
    93                          _aligned_free(a->dp);
    94  #else
    95                          free(a->dp);
    96  #endif
    97                          a->dp = NULL;
    98                  }
    99                  a->alloc = 0;
   100          }
   101  #endif
   102          if (a != NULL) {
   103                  a->used = 0;
   104                  a->sign = RLC_POS;
   105          }
   106  }
   107
   108  void bn_grow(bn_t a, int digits) {
   109  #if ALLOC == DYNAMIC
   110          dig_t *t;
   111
   112          if (a->alloc < digits) {
   113                  /* At least add RLC_BN_SIZE more digits. */
   114                  digits += (RLC_BN_SIZE * 2) - (digits % RLC_BN_SIZE);
   115                  t = (dig_t *)realloc(a->dp, (RLC_DIG / 8) * digits);
   116                  if (t == NULL) {
   117                          RLC_THROW(ERR_NO_MEMORY);
   118                          return;
   119                  }
   120                  a->dp = t;
   121                  /* Set the newly allocated digits to zero. */
   122                  a->alloc = digits;
   123          }
   124  #else /* ALLOC == AUTO || ALLOC == STACK */
   125          if (digits > RLC_BN_SIZE) {
   126                  RLC_THROW(ERR_NO_PRECI);
   127                  return;
   128          }
   129          (void)a;
   130  #endif
   131  }
   132
   133  void bn_trim(bn_t a) {
   134          if (a->used <= a->alloc) {
   135                  while (a->used > 0 && a->dp[a->used - 1] == 0) {
   136                          --(a->used);
   137                  }
   138                  /* Zero can't be negative. */
   139                  if (a->used <= 0) {
   140                          a->used = 1;
   141                          a->dp[0] = 0;
   142                          a->sign = RLC_POS;
   143                  }
   144          }
   145  }
