    88  /**
    89   * Represents a multiple precision integer.
    90   *
    91   * The field dp points to a vector of digits. These digits are organized
    92   * in little-endian format, that is, the least significant digits are
    93   * stored in the first positions of the vector.
    94   */
    95  typedef struct {
    96          /** The number of digits allocated to this multiple precision integer. */
    97          int alloc;
    98          /** The number of digits actually used. */
    99          int used;
   100          /** The sign of this multiple precision integer. */
   101          int sign;
   102  #if ALLOC == DYNAMIC
   103          /** The sequence of contiguous digits that forms this integer. */
   104          dig_t *dp;
   105  #elif ALLOC == STACK || ALLOC == AUTO
   106          /** The sequence of contiguous digits that forms this integer. */
   107          rlc_align dig_t dp[RLC_BN_SIZE];
   108  #endif
   109  } bn_st;
